def find_max(lst):
    if not lst:
        raise ValueError('List is empty')
    maximum = lst[0]
    for x in lst[1:]:
        if x > maximum:
            maximum = x
    return maximum

def char_frequency(s):
    freq = {}
    for c in s:
        freq[c] = freq.get(c, 0) + 1
    return freq

def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return False
    return True
